#include <bits/stdc++.h>
using namespace std;
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n;if(!(cin>>n)) return 0;priority_queue<long long,vector<long long>,greater<long long>> q;for(int i=0;i<n;i++){long long x;cin>>x;if(x>0) q.push(x);}long long ans=0;while(q.size()>1){long long a=q.top();q.pop();long long b=q.top();q.pop();long long c=a+b;ans+=c;q.push(c);}cout<<ans;return 0;}